-- calc_parenthoods_spouse_as_stated_count
-- Field: Parenthoods.SpouseAsStatedCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_parenthoods_spouse_as_stated_count(p_parenthood_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM marriages WHERE partner_a = (SELECT NULLIF(parent, '') FROM parenthoods WHERE parenthood_id = p_parenthood_id) AND partner_b = (SELECT NULLIF(child, '') FROM parenthoods WHERE parenthood_id = p_parenthood_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_parenthoods_spouse_as_mirrored_count
-- Field: Parenthoods.SpouseAsMirroredCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_parenthoods_spouse_as_mirrored_count(p_parenthood_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM marriages erb_r1 WHERE partner_a = (SELECT (SELECT NULLIF(child, '') FROM parenthoods WHERE parenthood_id = p_parenthood_id)) AND partner_b = (SELECT (SELECT NULLIF(parent, '') FROM parenthoods WHERE parenthood_id = p_parenthood_id)) AND ((SELECT (CASE WHEN calc_marriages_symmetric_is_on(erb_r1.marriage_id) THEN TRUE ELSE NULL END)::boolean))::boolean = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_parenthoods_is_contradiction
-- Field: Parenthoods.IsContradiction
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_parenthoods_is_contradiction(p_parenthood_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_parenthoods_disjoint_is_on(p_parenthood_id), FALSE) AND COALESCE(COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_parenthoods_spouse_as_stated_count(p_parenthood_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_parenthoods_spouse_as_mirrored_count(p_parenthood_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) > 0, FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

