-- calc_grandparenthoods_name
-- Field: Grandparenthoods.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_grandparenthoods_name(p_grandparenthood_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_grandparenthoods_links(p_grandparenthood_id) THEN (CONCAT(calc_grandparenthoods_grandparent_label(p_grandparenthood_id), ' is grandparent of ', calc_grandparenthoods_grandchild_label(p_grandparenthood_id)))::text ELSE (CONCAT('(', (SELECT NULLIF(upper_link, '') FROM grandparenthoods WHERE grandparenthood_id = p_grandparenthood_id), ' does not lead to ', (SELECT NULLIF(lower_link, '') FROM grandparenthoods WHERE grandparenthood_id = p_grandparenthood_id), ')'))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_grandparenthoods_links
-- Field: Grandparenthoods.Links
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grandparenthoods_links(p_grandparenthood_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE(calc_grandparenthoods_upper_child(p_grandparenthood_id), '') = COALESCE(calc_grandparenthoods_lower_parent(p_grandparenthood_id), ''))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grandparenthoods_holds
-- Field: Grandparenthoods.Holds
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grandparenthoods_holds(p_grandparenthood_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_grandparenthoods_links(p_grandparenthood_id), FALSE) AND COALESCE(calc_grandparenthoods_chain_is_on(p_grandparenthood_id), FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

