-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grade_level_records_is_current(p_grade_level_record_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_on FROM grade_level_records WHERE grade_level_record_id = p_grade_level_record_id), FALSE), FALSE) AND COALESCE(COALESCE((SELECT stated_seq FROM grade_level_records WHERE grade_level_record_id = p_grade_level_record_id), 0) = COALESCE(calc_grade_level_records_individual_latest_seq(p_grade_level_record_id), 0), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_grade_level_records_key_is_canonical
