-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_grade_level_records_key_is_canonical(p_grade_level_record_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((SELECT NULLIF(grade_level_record_id, '') FROM grade_level_records WHERE grade_level_record_id = p_grade_level_record_id), '') = COALESCE(CONCAT((SELECT NULLIF(individual, '') FROM grade_level_records WHERE grade_level_record_id = p_grade_level_record_id), '|grade|', (SELECT stated_seq FROM grade_level_records WHERE grade_level_record_id = p_grade_level_record_id)), ''))::boolean;
$$ LANGUAGE sql STABLE;

